from collections.abc import Mapping, Sequence
import math


def _finite_number(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be numeric")
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return value


def classify_rows(columns, limit=0.05):
    if not isinstance(columns, Mapping):
        raise TypeError("columns must be a mapping")
    limit = _finite_number(limit, "limit")
    if limit < 0:
        raise ValueError("limit must be non-negative")
    result = {}
    length = None
    for name, values in columns.items():
        if not isinstance(name, str):
            raise TypeError("column names must be strings")
        if not name:
            raise ValueError("column names must not be empty")
        if name == "Decision":
            raise ValueError("Decision is reserved")
        if isinstance(values, (str, bytes)) or not isinstance(values, Sequence):
            raise TypeError("column values must be sequences")
        copied = [_finite_number(value, f"{name} value") for value in values]
        if length is None:
            length = len(copied)
        elif len(copied) != length:
            raise ValueError("columns must have equal length")
        result[name] = copied
    if length is None:
        length = 0
    decisions = []
    names = list(result)
    for row in range(length):
        values = [result[name][row] for name in names]
        if any(value >= limit for value in values):
            decisions.append(1)
        elif any(value < -limit for value in values):
            decisions.append(-1)
        else:
            decisions.append(0)
    result["Decision"] = decisions
    return result

